import type { Mount } from "./CarouselControls.props";

// The island adds the previous and next buttons to a carousel. The slides
// are server HTML in a scroll container with CSS scroll snap, so with no
// script a user scrolls them with touch, a wheel or the arrow keys.
const mount: Mount = (root, props, ctx) => {
  const viewport = document.getElementById(props.viewport);
  if (!viewport) throw new Error(`no viewport with the id ${props.viewport}`);
  const c = props.classes;
  const vertical = props.orientation === "vertical";
  const slides = (): HTMLElement[] => [...viewport.children].filter((el): el is HTMLElement => el instanceof HTMLElement);

  root.className = c.root;
  const button = (label: string, text: string): HTMLButtonElement => {
    const b = root.appendChild(document.createElement("button"));
    b.type = "button";
    b.className = c.button;
    b.setAttribute("aria-label", label);
    b.setAttribute("aria-controls", props.viewport);
    b.textContent = text;
    return b;
  };
  const prev = button(props.previousLabel, vertical ? "↑" : "←");
  const status = root.appendChild(document.createElement("div"));
  status.className = c.status;
  status.setAttribute("aria-live", "polite");
  status.setAttribute("aria-atomic", "true");
  const next = button(props.nextLabel, vertical ? "↓" : "→");

  const offset = (el: HTMLElement): number => (vertical ? el.offsetTop - viewport.offsetTop : el.offsetLeft - viewport.offsetLeft);
  const position = (): number => (vertical ? viewport.scrollTop : viewport.scrollLeft);

  // current is the slide whose start is nearest to the scroll position.
  const current = (): number => {
    let best = 0;
    let distance = Infinity;
    slides().forEach((slide, i) => {
      const d = Math.abs(offset(slide) - position());
      if (d < distance) {
        best = i;
        distance = d;
      }
    });
    return best;
  };

  let shown = -1;
  const update = (): void => {
    const all = slides();
    const index = current();
    prev.disabled = index <= 0;
    next.disabled = index >= all.length - 1;
    all.forEach((slide, i) => slide.setAttribute("data-current", String(i === index)));
    if (index !== shown) {
      shown = index;
      status.textContent = props.statusText.replace("{n}", String(index + 1)).replace("{count}", String(all.length));
    }
  };

  const go = (index: number): void => {
    const all = slides();
    const slide = all[Math.max(0, Math.min(index, all.length - 1))];
    if (!slide) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const to = offset(slide);
    viewport.scrollTo({ [vertical ? "top" : "left"]: to, behavior: reduce ? "auto" : "smooth" });
  };

  const listen = { signal: ctx.abort };
  prev.addEventListener("click", () => go(current() - 1), listen);
  next.addEventListener("click", () => go(current() + 1), listen);
  viewport.addEventListener("scroll", update, { ...listen, passive: true });
  // The arrow keys move one slide; the browser alone scrolls a few pixels.
  viewport.addEventListener(
    "keydown",
    (event) => {
      const back = vertical ? "ArrowUp" : "ArrowLeft";
      const forward = vertical ? "ArrowDown" : "ArrowRight";
      if (event.key !== back && event.key !== forward && event.key !== "Home" && event.key !== "End") return;
      event.preventDefault();
      if (event.key === "Home") go(0);
      else if (event.key === "End") go(slides().length - 1);
      else go(current() + (event.key === forward ? 1 : -1));
    },
    listen,
  );
  update();

  return () => {
    for (const slide of slides()) slide.removeAttribute("data-current");
    root.replaceChildren();
    root.className = "";
  };
};

export default mount;

// Package carousel is a row of slides in a scroll container with CSS scroll
// snap. The CarouselControls island adds the previous and next buttons.
package carousel

import "github.com/alternayte/gx"

// Orientation is the direction of the slides of a carousel.
type Orientation string

// The orientations of carousel.Carousel.
const (
	Horizontal Orientation = "horizontal"
	Vertical   Orientation = "vertical"
)

// CarouselControlsProps are the props of the island that draws the
// buttons. The island scrolls the element with the id Viewport.
type CarouselControlsProps struct {
	// Viewport is the id of the scroll container.
	Viewport string `json:"viewport"`
	// Orientation is "horizontal" or "vertical".
	Orientation string `json:"orientation"`
	// PreviousLabel and NextLabel name the two buttons.
	PreviousLabel string `json:"previousLabel"`
	NextLabel     string `json:"nextLabel"`
	// StatusText is the text of the position, with {n} and {count}.
	StatusText string `json:"statusText"`
	// Classes holds the classes of the parts. They are Go constants, so
	// the stylesheet build sees them.
	Classes ControlClasses `json:"classes"`
}

// ControlClasses are the classes of the parts that the island draws.
type ControlClasses struct {
	Root   string `json:"root"`
	Button string `json:"button"`
	Status string `json:"status"`
}

const rootClass = "flex w-full max-w-sm flex-col gap-2"

// viewportClass is the classes of the scroll container. The slides snap to
// its start.
var viewportClass = gx.Enum[Orientation]{
	Horizontal: "flex snap-x snap-mandatory overflow-x-auto overflow-y-hidden rounded-md outline-none [scrollbar-width:none] focus-visible:ring-[3px] focus-visible:ring-ring/50",
	Vertical:   "flex h-64 snap-y snap-mandatory flex-col overflow-x-hidden overflow-y-auto rounded-md outline-none [scrollbar-width:none] focus-visible:ring-[3px] focus-visible:ring-ring/50",
}

// itemClass is the classes of one slide: as wide and as high as the scroll
// container.
const itemClass = "min-h-0 min-w-0 shrink-0 grow-0 basis-full snap-start"

// statusText is the text of the position. The island fills in the numbers.
const statusText = "Slide {n} of {count}"

var controlClasses = ControlClasses{
	Root:   "flex items-center justify-center gap-3",
	Button: "inline-flex size-8 items-center justify-center rounded-full border border-border bg-background text-sm shadow-xs outline-none hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
	Status: "min-w-24 text-center text-sm text-muted-foreground",
}

// label returns the accessible name; a zero value is "Carousel".
func (p CarouselProps) label() string {
	if p.Label == "" {
		return "Carousel"
	}
	return p.Label
}

// orientation returns the direction; a zero value is Horizontal.
func (p CarouselProps) orientation() Orientation {
	if p.Orientation == Vertical {
		return Vertical
	}
	return Horizontal
}

func (p CarouselProps) viewportID() string { return p.Id + "-viewport" }
